function courseUiWorkspaceReadable(workspace){if(!workspace||role!=='teacher')return false;if(workspace.kind==='course')return allCourseIds().includes(workspace.courseId)&&workspace.path==='/account/courses/'+encodeURIComponent(workspace.courseId);if(workspace.kind==='fees')return workspace.path==='/account/fees';return ['catalog','timetable'].includes(workspace.kind)&&workspace.path==='/account';}
