function persistCourseUiHistory(){if(courseUiRestoring)return;const state=history.state?.[courseUiHistoryKey];if(state?.version!==1||state.identity!==courseUiIdentity()||state.workspace?.path!==path())return;const workspace=captureCourseUiWorkspace();if(!workspace||workspace.kind!==state.workspace.kind)return;if(workspace.kind==='fees'){workspace.feeId=state.workspace.feeId;workspace.courseId=state.workspace.courseId;}storeCourseUiHistory(workspace);}
function applyCourseUiWorkspace(workspace){if(workspace.kind==='course'){tab='catalog';courseDetailTab=workspace.detailTab==='materials'?'materials':'general';if(validISODate(workspace.month))courseDetailMonth=timetableDateObject(workspace.month);}else if(workspace.kind==='fees'){tab='fees';feeSearch=String(workspace.feeSearch||'');feeFilter=['normal','single','multiple'].includes(workspace.feeFilter)?workspace.feeFilter:'normal';}else if(workspace.kind==='catalog'){tab='catalog';courseSearch=String(workspace.search||'');courseStatusFilter=workspace.status==='deleted'?'deleted':'active';courseCategoryFilter=String(workspace.category||'');courseLevelFilter=String(workspace.level||'');courseSortKey=['courseCode','courseName','category','level'].includes(workspace.sortKey)?workspace.sortKey:'courseCode';courseSortDirection=workspace.sortDirection==='desc'?'desc':'asc';}else tab='overview';}
