 if(sharedMode&&authUser?.role==='teacher'){try{const result=await refreshSharedSchedules({paint:false});if(result?.error)throw result.error;}catch(error){if(opening===courseUiOpening&&context===courseTimetableOpeningContext())toast(sharedErrorText(error));return;}}
 if(opening!==courseUiOpening||context!==courseTimetableOpeningContext()||!activeCourseIds().includes(id))return;
 const source=captureCourseUiWorkspace(opener),preferences=captureTimetablePreferences();storeCourseUiHistory(source);courseTimetableOrigin={identity:courseUiIdentity(),workspace:source,preferences,detailOrigin:courseDetailOrigin};const dates=courseScheduleGroups(id,month).flatMap(group=>group.dates).sort(),target=dates.includes(timetableDate)?timetableDate:dates[0]||(source.kind==='catalog'?timetableDate:timetableDateKey(month));timetableLessonFilter={course:id};timetableSearch='';timetableResourceSearch='';timetableSelections={rooms:[],teachers:[]};timetableNamedFilters=normalizeTimetableFilterState({...timetableNamedFilters,hiddenResources:{rooms:[],teachers:[]},hiddenPresets:[],only:null,filters:timetableNamedFilters.filters.map(row=>({...row,visible:true}))});timetableClassTypeFilter='';selectTimetableDate(target);navigateCourseUi({kind:'timetable',path:'/account'});
