 const generation=scheduleGeneration,job={},lookup=action+':'+current.id+':'+current.version,key=sharedScheduleMutationKeys.get(lookup)||newOperationKey();sharedScheduleMutationKeys.set(lookup,key);scheduleSaveJob=job;scheduleSaving=true;
