 try{const result=current.undoSequence?await sharedClient.restoreScheduleOccurrence(current,current.undoSequence,current.undoScope,key):await sharedClient[action==='delete'?'deleteSchedule':'restoreSchedule'](current,key);if(generation!==scheduleGeneration||scheduleSaveJob!==job)return;scheduleGeneration++;sharedSchedulesRevision='';db.schedules=db.schedules.filter(item=>item.id!==current.id);if(action==='delete')sharedDeletedSchedule=result.schedule;else{db.schedules.push(result.schedule);sharedDeletedSchedule=null;}modal='';scheduleDraft=null;selectedTimetableLesson=null;render();toast(action==='delete'?t('時間安排已刪除，可按撤銷還原。','Schedule deleted. Use Undo to restore it.'):t('時間安排已還原','Schedule restored'));}
