const scheduleMinutes=time=>Number(time.slice(0,2))*60+Number(time.slice(3));
const scheduleTime=minutes=>String(Math.floor(minutes/60)%24).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0');
function scheduleTextColor(color){let safe=/^#[0-9a-f]{6}$/i.test(color||'')?color:'#27777b',channels=[1,3,5].map(i=>parseInt(safe.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return channels[0]*.2126+channels[1]*.7152+channels[2]*.0722>.26?'#253d3b':'#ffffff'}
function scheduleResourceOptions(kind){if(sharedMode)return sharedSchedulingResources.filter(r=>r.kind===kind&&r.active).map(r=>r.id);let stored=kind==='teacher'?previewTeachers.map(p=>p.name):[],values=[...stored,...db.classes.map(c=>c[kind]),...scheduleResourceRecords().map(s=>s?.[kind]),scheduleDraft?.[kind]];return [...new Set(values.filter(Boolean).map(String))].sort()}
