function scheduleOccurs(schedule,key){if(schedule.activityDeleted||!validISODate(key)||key<schedule.startDate||!schedule.weekdays.includes(timetableDateObject(key).getDay()))return false;if(schedule.endMode==='date'&&key>schedule.endDate)return false;if(schedule.endMode==='count'){let start=new Date(schedule.startDate+'T00:00:00Z'),end=new Date(key+'T00:00:00Z'),offset=Math.round((end-start)/86400000),weeks=Math.floor(offset/7),count=weeks*schedule.weekdays.length;for(let i=0;i<=offset%7;i++)if(schedule.weekdays.includes((start.getUTCDay()+i)%7))count++;return count<=schedule.count}return true}
