function moveLeadColumnDraft(key,index){if(role!=='teacher'||!leadColumnDraft||!leadColumnDraft.includes(key)||!Number.isInteger(index))return false;let from=leadColumnDraft.indexOf(key),to=Math.max(0,Math.min(leadColumnDraft.length-1,index));if(from===to)return false;leadColumnDraft.splice(from,1);leadColumnDraft.splice(to,0,key);return true}
function announceLeadColumn(key){document.querySelector('#lead-column-status').textContent=t(`${leadColumnLabel(key)}：第 ${leadColumnDraft.indexOf(key)+1} 個欄位`,`${leadColumnLabel(key)}: column ${leadColumnDraft.indexOf(key)+1}`)}
function startLeadColumnDrag(e){let handle=e.target.closest?.('[data-lead-column-handle]');if(!handle||role!=='teacher'||!leadColumnDraft||e.isPrimary===false||(e.button!==undefined&&e.button!==0))return false;let key=handle.dataset.leadColumnHandle;if(!leadColumnDraft.includes(key))return false;e.preventDefault();leadColumnDrag={key,handle,pointerId:e.pointerId,x:e.clientX,y:e.clientY,before:[...leadColumnDraft],frame:null,capture:document.querySelector('#lead-columns-body')};leadColumnDrag.capture.setPointerCapture?.(e.pointerId);handle.setAttribute('aria-pressed','true');handle.closest('li').classList.add('is-dragging');return true}
function stepLeadColumnDrag(){let drag=leadColumnDrag;if(!drag||role!=='teacher'||!leadColumnDraft)return;let body=document.querySelector('#lead-columns-body'),list=document.querySelector('#lead-shown-columns'),bounds=body.getBoundingClientRect(),edge=42,speed=drag.y<bounds.top+edge?-12:drag.y>bounds.bottom-edge?12:0;body.scrollTop+=speed;let others=[...list.querySelectorAll('[data-lead-column]')].filter(row=>row.dataset.leadColumn!==drag.key),index=others.filter(row=>{let r=row.getBoundingClientRect();return drag.y>r.top+r.height/2}).length;if(moveLeadColumnDraft(drag.key,index)){let source=drag.handle.closest('li');list.insertBefore(source,others[index]||null);announceLeadColumn(drag.key)}if(speed&&leadColumnDrag&&window.requestAnimationFrame)drag.frame=window.requestAnimationFrame(()=>{drag.frame=null;stepLeadColumnDrag()})}
function moveLeadColumnDrag(e){if(!leadColumnDrag||e.pointerId!==leadColumnDrag.pointerId)return;leadColumnDrag.x=e.clientX;leadColumnDrag.y=e.clientY;e.preventDefault();if(!leadColumnDrag.frame)stepLeadColumnDrag()}
function finishLeadColumnDrag(cancel=false){let drag=leadColumnDrag;if(!drag)return;if(drag.frame)window.cancelAnimationFrame?.(drag.frame);leadColumnDrag=null;if(cancel)leadColumnDraft=drag.before;if(drag.capture.hasPointerCapture?.(drag.pointerId))drag.capture.releasePointerCapture(drag.pointerId);if(leadColumnDraft){refreshLeadColumns(drag.key);announceLeadColumn(drag.key)}}
