document.addEventListener('change',e=>{if(e.target.id==='scheduling-resource-status'&&resourceManager&&!resourceDraft&&['active','inactive','all'].includes(e.target.value)){resourceManager.status=e.target.value;drawSchedulingResources('#scheduling-resource-status');}});
document.addEventListener('change',e=>{if(e.target.dataset?.resourceSelection||e.target.dataset?.resourceLegacyClear)scheduleResourcePickerChanged(e.target);});

document.addEventListener('change',event=>{if(!canManagePeople()||peopleEditorDraft||!isPeopleView())return;const target=event.target;if(target.id==='people-sort'&&['displayName','createdAt'].includes(target.value))peopleList.sort=target.value;else if(target.id==='people-direction'&&['asc','desc'].includes(target.value))peopleList.direction=target.value;else return;peopleList.page=1;render();});

document.addEventListener('change',event=>{if(event.target.id==='availability-public-course-filter'){changePublicTimetableCourse(event.target.value);return;}if(event.target.id==='availability-preview-course-filter'){changePublicTimetableCourse(event.target.value,{preview:true});return;}if(event.target.id==='availability-preview-type'){changePublicAvailabilityType(event.target.value,{preview:true});return;}if(event.target.id==='availability-public-type'){changePublicAvailabilityType(event.target.value);return;}if(event.target.id==='availability-preview-days'){changePublicAvailabilityDays(event.target.value,{preview:true});return;}if(event.target.id==='availability-public-days'){changePublicAvailabilityDays(event.target.value);return;}if(['availability-mode','availability-occurrence'].includes(event.target.id)){syncAvailabilitySource();return;}if(sharedMode&&event.target.id==='availability-public-from')changePublicAvailabilityDate(event.target.value);});


document.addEventListener('change',event=>{if(event.target.name==='classTypeId')updateClassTypeChoice(event.target);if(event.target.id==='tt-class-type-filter'&&classTypesEnabled()&&!modal){const value=event.target.value;if(value===''||value==='__none'||sharedClassTypes.some(type=>type.id===value)||db.schedules.some(item=>item.classType?.id===value)||sharedScheduleOccurrences.some(occ=>occ.item.classType?.id===value)){timetableClassTypeFilter=value;render();document.querySelector('#tt-class-type-filter')?.focus();}}});

document.addEventListener('scroll',()=>{if(!modal)persistCourseUiHistory();},true);

// Keep the optional colour picker inactive until an administrator chooses to use it.
document.addEventListener('change',event=>{if(event.target.id!=='course-public-colour-enabled'||courseSaving||sharedMode&&authUser?.role!=='admin')return;const form=event.target.closest?.('#create-course-editor,#course-metadata-editor'),picker=form?.querySelector('[name=publicColor]');if(picker){picker.disabled=!event.target.checked;const label=picker.closest?.('.course-public-colour-picker');if(label)label.hidden=!event.target.checked;}const state=form?.querySelector('[data-public-colour-state]');if(state)state.textContent=event.target.checked?t('已選擇顏色','Colour selected'):t('未設定','Not set');});
